use super::super::{ClassificationKind, Facts};
use super::*;
use std::collections::BTreeMap;

#[test]
fn actual_eh_vectors_preserve_direct_actions_flags_and_row_order() {
    let cases: Vec<Value> = serde_json::from_str(SOURCE_CASES).unwrap();
    assert_eq!(cases.len(), 52);
    for case in cases {
        let mut state = ClassificationState::capture(case["before"].as_array().unwrap()).unwrap();
        let left: Vec<String> = serde_json::from_value(case["left"].clone()).unwrap();
        let joined: Vec<String> = serde_json::from_value(case["joined"].clone()).unwrap();
        let step = state
            .membership_step(&left, &joined, case["allow"].as_bool().unwrap())
            .unwrap();
        assert_eq!(
            json!(step.action_ids()),
            case["actions"],
            "{}",
            case["name"]
        );
        let expected = ClassificationState::capture(case["after"].as_array().unwrap()).unwrap();
        assert_eq!(state.shadow, expected.shadow, "{}", case["name"]);
        for row in step.rows() {
            assert_eq!(state.row(&row.id).unwrap(), *row);
        }
    }
}

#[test]
fn direct_membership_keeps_unknown_flags_until_actual_processor_step() {
    let mut state = ClassificationState::capture(&[json!({"id":"C12345678","name":"MiXeD","_name_lc":"","isUnknown":true,"isNonExistent":true})]).unwrap();
    let member = state
        .membership_step(&[], &["C12345678".into()], true)
        .unwrap();
    assert_eq!(member.action_ids(), ["C12345678"]);
    assert_eq!(
        state.row("C12345678").unwrap().kind,
        ClassificationKind::NonExistent
    );
    assert_eq!(state.shadow[0]["_name_lc"], "");
    assert_eq!(state.shadow[0]["isUnknown"], true);
    let facts = Facts {
        self_id: "USELF".into(),
        current_team: "TONE".into(),
        omit_team: "TONE".into(),
        retain_public_membership_on_archive: false,
        members: BTreeMap::new(),
    };
    let step = state
        .step(&[json!({"id":"C12345678","name":"MiXeD"})], &facts, false)
        .unwrap();
    assert_eq!(step.action_ids(), ["C12345678"]);
    assert_eq!(
        state.row("C12345678").unwrap().kind,
        ClassificationKind::Existing
    );
}

#[test]
fn unavailable_target_refuses_whole_action_but_unrelated_gap_does_not() {
    let mut state =
        ClassificationState::capture(&[json!({"id":"C12345678","name":"One","_name_lc":"one"})])
            .unwrap();
    state.unavailable.insert("C22222222".into());
    let before = state.shadow.clone();
    assert!(
        state
            .membership_step(&[], &["C12345678".into(), "C22222222".into()], true)
            .is_err()
    );
    assert_eq!(state.shadow, before);
    assert!(
        state
            .membership_step(&[], &["C12345678".into()], true)
            .is_ok()
    );
    let step = state
        .membership_step(&["C33333333".into()], &[], true)
        .unwrap();
    assert!(step.action_ids().is_empty());
    assert_eq!(
        state.row("C33333333").unwrap().kind,
        ClassificationKind::Absent
    );
}
